#!/bin/bash
var=$1

echo "CAM ISO set $var"
case $var in
	100)
		i2ctransfer -f -y -a 2 w4@0x3c 0x50 0x08 0x00 0x64
		i2ctransfer -f -y -a 1 w4@0x3c 0x50 0x08 0x00 0x64	
		;;
	200)
		i2ctransfer -f -y -a 2 w4@0x3c 0x50 0x08 0x00 0xC8
		i2ctransfer -f -y -a 1 w4@0x3c 0x50 0x08 0x00 0xC8
		;;
	400)
		i2ctransfer -f -y -a 2 w4@0x3c 0x50 0x08 0x01 0x90
		i2ctransfer -f -y -a 1 w4@0x3c 0x50 0x08 0x01 0x90
		;;
	800)
		i2ctransfer -f -y -a 2 w4@0x3c 0x50 0x08 0x03 0x20
		i2ctransfer -f -y -a 1 w4@0x3c 0x50 0x08 0x03 0x20
		;;
	1600)
		i2ctransfer -f -y -a 2 w4@0x3c 0x50 0x08 0x06 0x40
		i2ctransfer -f -y -a 1 w4@0x3c 0x50 0x08 0x06 0x40
		;;
	*) 
		echo "Wrong option '$1'"; exit 1;;
esac
	